def guide_plan(g, inp, plan, weight, *, span_sides=False, chain_sides=False):
    """Weight virtual guides using the two physical end leads of each side.

    Chain headers already carry these lengths independently of their interior
    arcs and original path pieces. Never read a chain header as a circle.
    Collapsed separator sides and one-ended tapers retain their existing guide.
    """
    owner=c.V(g,g.node('GeometryNodeInputIndex').outputs[0])
    mouths=inp.outputs['Mouths'];corners=inp.outputs['Corners']
    nxt=g.math('MODULO',owner+1.,c._count(g,mouths))
    if chain_sides:
        left=c._read(g,corners,'st_ca_la',owner)
        right=c._read(g,corners,'st_ca_lb',owner)
        eligible=1.
    else:
        left=c._read(g,mouths,'st_cj_parameter',owner)-c._read(g,corners,'st_cc_sa',owner)
        right=c._read(g,mouths,'st_cj_parameter',nxt)-c._read(g,corners,'st_cc_sb',owner)
        if span_sides:
            left=g.math('ABSOLUTE',left);right=g.math('ABSOLUTE',right)
            eligible=1.
        else:
            kind=c._read(g,corners,'st_ct_kind',owner,'INT')
            eligible=g.math('MAXIMUM',g.math('COMPARE',kind,0.),g.math('COMPARE',kind,2.))
    if span_sides or chain_sides:
        first=g.math('COMPARE',c._read(g,mouths,'st_cj_half',owner,'INT'),-1.)
        last=g.math('COMPARE',c._read(g,mouths,'st_cj_half',nxt,'INT'),1.)
        eligible*=(1.-first)*(1.-last)
    contrast=(left-right)/g.math('MAXIMUM',left+right,1e-12)
    value=weight*contrast*contrast*eligible
    if chain_sides:
        present=1.
        for key in ('st_ca_la','st_ca_lb'):
            attr=g.node('GeometryNodeInputNamedAttribute');attr.data_type='FLOAT'
            attr.inputs['Name'].default_value=key
            present*=c._stat(g,corners,c.V(g,attr.outputs['Exists'])*
                            (1.-g.math('LESS_THAN',attr.outputs['Attribute'],0.)))
        # A missing header must fail the primitive's weight-range guard.
        value=c.choose(g,present,value,-1.)
    return c._store(g,plan,'st_lc_guide_weight',value)


def replace_saved_guide_alignment(root, *, weight=.5):
    """Copy saved local adapters; preserve complete side programs and guards.

    Only virtual guide sampling changes. Existing core placement, band grading,
    boundary samplers, profiles and fallback constructors remain connected.
    This opt-in migration also admits multi-site original span/chain adapters.
    """
    if not 0. < weight <= 1.:raise ValueError('Maximum guide weight must be in (0, 1]')
    memo,primitives,changed={},{},[]
    def visit(tree):
        if tree in memo:return memo[tree]
        if tree.name.startswith('Prochitecture Streets / Local corner layout adapter v1'):
            if tree.get('st_corner_guide_alignment'):
                raise ValueError('Saved adapter already has a guide-alignment policy')
            result=tree.copy()
            g=c.Graph.__new__(c.Graph);g.g=result;g.count=len(result.nodes);g.frame=None
            inp,=[n for n in result.nodes if n.type=='GROUP_INPUT']
            call,=[n for n in result.nodes if n.type=='GROUP' and
                   n.label=='Local corner patterns and direct quad center']
            link,=call.inputs['Plan'].links
            plan=guide_plan(g,inp,link.from_socket,weight,
                            span_sides='Original span sides' in tree.name,
                            chain_sides='Original chain sides' in tree.name)
            original=call.node_tree
            if original not in primitives:primitives[original]=local.with_saved_guide_alignment(original)
            assign_group(call,primitives[original])
            g.bind(plan,call.inputs['Plan'])
            result['st_corner_guide_alignment']='end_lead_contrast_v1'
            result['st_corner_maximum_guide_weight']=weight
            changed.append(tree.name)
        else:
            children=[(n.name,visit(n.node_tree)) for n in tree.nodes if n.type=='GROUP' and n.node_tree]
            children=[(name,child) for name,child in children if child!=tree.nodes[name].node_tree]
            result=tree.copy() if children else tree
            for name,child in children:assign_group(result.nodes[name],child)
        memo[tree]=result;return result
    roots=root if isinstance(root,(list,tuple)) else [root]
    results=[visit(tree) for tree in roots]
    if not changed:raise ValueError('No saved local corner adapters found')
    return (results if isinstance(root,(list,tuple)) else results[0]),sorted(set(changed))


def replace_corner_sources(root, *, row_checks=False):
    """Use compact lookup sources in copied local adapters, retaining guards."""
    memo,changed={},[]
    def visit(tree):
        if tree in memo:return memo[tree]
        if tree.name.startswith('Prochitecture Streets / Local corner layout adapter v1'):
            matches=[n for n in tree.nodes if n.type=='GROUP' and
                     n.label=='Original analytic boundary and ray samples; no interior descent']
            if len(matches)!=1:raise ValueError('Expected one original corner sample source')
            raw=matches[0];name=raw.node_tree.name
            if not name.startswith('Prochitecture Streets / Ordinary cyclic direct quad layout v1'):
                raise ValueError('Qualify composed station adapters before compacting their sources')
            if 'Compact corner source' in name:return tree
            replacement=cyclic.build(compound=False,continuations='Curb continuations' in name,
                port_paths=True,span_compounds='Original span sides' in name,
                chain_sides='Original chain sides' in name,coarse_seed=False,
                interpolation='Exact entrance rays' in name,compact_corner_source=True,
                compact_row_checks=row_checks)
            result=tree.copy();assign_group(result.nodes[raw.name],replacement)
            changed.append(name)
        else:
            children=[(n.name,visit(n.node_tree)) for n in tree.nodes if n.type=='GROUP' and n.node_tree]
            children=[(key,child) for key,child in children if child!=tree.nodes[key].node_tree]
            result=tree.copy() if children else tree
            for key,child in children:assign_group(result.nodes[key],child)
        memo[tree]=result;return result
    roots=root if isinstance(root,(list,tuple)) else [root]
    results=[visit(tree) for tree in roots]
    if not changed:raise ValueError('No uncompacted local corner sample sources found')
    return (results if isinstance(root,(list,tuple)) else results[0]),sorted(set(changed))


def supports(original, *, logical_sides=False):
    return _supports(original) or (logical_sides and original.name.startswith(
        'Prochitecture Streets / Original chain profiled patch v1')
        and original.name.endswith(' / Local frame v1'))


